var planning_view_default = ".dreamglows-progress-bar-container {\r\n    width: 100px;\r\n    height: 8px;\r\n    background: var(--background-modifier-border);\r\n    border-radius: 4px;\r\n    position: relative;\r\n    overflow: hidden;\r\n    margin-right: 1rem;\r\n}\r\n\r\n.dreamglows-progress-bar {\r\n    height: 100%;\r\n    background: var(--text-accent);\r\n    border-radius: 4px;\r\n    transition: width 0.3s ease;\r\n}\r\n\r\n.dreamglows-progress-text {\r\n    position: absolute;\r\n    right: -25px;\r\n    top: 50%;\r\n    transform: translateY(-50%);\r\n    color: var(--text-muted);\r\n    font-size: 0.7em;\r\n    white-space: nowrap;\r\n}\r\n\r\n/* Styles pour les tâches */\r\n.dreamglows-tasks-list {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n    width: 100%;\r\n    padding: 8px 0;\r\n}\r\n\r\n.dreamglows-task-item {\r\n    width: 100%;\r\n    padding: 0 8px;\r\n}\r\n\r\n.dreamglows-task-item-content {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    width: 100%;\r\n    padding: 8px;\r\n    border-radius: 4px;\r\n    transition: all 0.2s ease;\r\n    cursor: pointer;\r\n}\r\n\r\n.dreamglows-task-item-content:hover {\r\n    background-color: var(--background-modifier-hover);\r\n    transform: translateX(4px);\r\n}\r\n\r\n.dreamglows-task-checkbox {\r\n    width: 18px;\r\n    height: 18px;\r\n    border: 2px solid var(--text-muted);\r\n    border-radius: 4px;\r\n    transition: all 0.2s ease;\r\n    flex-shrink: 0;\r\n}\r\n\r\n.dreamglows-task-checkbox.checked {\r\n    background-color: var(--text-accent);\r\n    border-color: var(--text-accent);\r\n}\r\n\r\n.dreamglows-task-item-content:hover .dreamglows-task-checkbox:not(.checked) {\r\n    border-color: var(--text-accent);\r\n    transform: scale(1.1);\r\n}\r\n\r\n.dreamglows-task-label {\r\n    flex: 1;\r\n    transition: all 0.2s ease;\r\n    padding: 4px 0;\r\n}\r\n\r\n.dreamglows-task-label.done {\r\n    text-decoration: line-through;\r\n    color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-task-item-content:hover .dreamglows-task-label:not(.done) {\r\n    color: var(--text-accent);\r\n}\r\n\r\n.dreamglows-task-delete {\r\n    opacity: 0;\r\n    color: var(--text-muted);\r\n    padding: 4px;\r\n    border-radius: 4px;\r\n    cursor: pointer;\r\n    transition: all 0.2s ease;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n}\r\n\r\n.dreamglows-task-item-content:hover .dreamglows-task-delete {\r\n    opacity: 1;\r\n}\r\n\r\n.dreamglows-task-delete:hover {\r\n    color: var(--text-error);\r\n    background-color: var(--background-modifier-error);\r\n    transform: scale(1.1);\r\n}\r\n\r\n.dreamglows-task-actions {\r\n    display: flex;\r\n    gap: 4px;\r\n    align-items: center;\r\n}\r\n\r\n.dreamglows-task-action-button {\r\n    opacity: 0;\r\n    padding: 4px;\r\n    border-radius: 4px;\r\n    border: none;\r\n    cursor: pointer;\r\n    font-size: 14px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    transition: all 0.2s ease;\r\n    background: var(--background-modifier-border);\r\n    color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-task-item-content:hover .dreamglows-task-action-button {\r\n    opacity: 1;\r\n}\r\n\r\n.dreamglows-task-action-button:hover {\r\n    transform: scale(1.1);\r\n}\r\n\r\n.dreamglows-task-action-button.optimizer:hover {\r\n    background: var(--interactive-accent);\r\n    color: var(--text-on-accent);\r\n}\r\n\r\n.dreamglows-task-action-button.generator:hover {\r\n    background: var(--text-accent);\r\n    color: var(--text-on-accent);\r\n}\r\n\r\n.dreamglows-planning-view {\r\n    display: flex;\r\n    flex-direction: column;\r\n    height: 100%;\r\n    overflow: hidden;\r\n}\r\n\r\n.dreamglows-planning-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    padding: 1rem;\r\n    background: var(--background-secondary);\r\n    border-bottom: 1px solid var(--background-modifier-border);\r\n}\r\n\r\n.dreamglows-planning-header h2 {\r\n    margin: 0;\r\n    font-size: 1.5em;\r\n    color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-planning-controls {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 0.5rem;\r\n}\r\n\r\n.dreamglows-planning-controls button {\r\n    padding: 0.25rem 0.5rem;\r\n    border: 1px solid var(--background-modifier-border);\r\n    border-radius: 4px;\r\n    background: var(--background-primary);\r\n    color: var(--text-normal);\r\n    cursor: pointer;\r\n}\r\n\r\n.dreamglows-planning-controls button:hover {\r\n    background: var(--background-primary-alt);\r\n}\r\n\r\n.dreamglows-planning-controls span {\r\n    padding: 0.25rem 0.5rem;\r\n    color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-planning-content {\r\n    flex: 1;\r\n    overflow-y: auto;\r\n}\r\n\r\n.dreamglows-planning-filters {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 12px;\r\n    padding: 16px;\r\n    background: var(--background-secondary);\r\n    border-radius: 8px;\r\n}\r\n\r\n.dreamglows-search-row input {\r\n    width: 100%;\r\n    padding: 8px;\r\n    border-radius: 4px;\r\n    border: 1px solid var(--background-modifier-border);\r\n}\r\n\r\n.dreamglows-filters-row {\r\n    display: flex;\r\n    gap: 16px;\r\n    flex-wrap: wrap;\r\n}\r\n\r\n.dreamglows-filter-group {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n}\r\n\r\n.dreamglows-filter-group label {\r\n    font-size: 0.8em;\r\n    color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-filter-group select {\r\n    padding: 4px 8px;\r\n    border-radius: 4px;\r\n    border: 1px solid var(--background-modifier-border);\r\n}\r\n\r\n.dreamglows-sort-controls {\r\n    display: flex;\r\n    gap: 4px;\r\n    align-items: center;\r\n}\r\n\r\n.dreamglows-sort-direction {\r\n    padding: 4px 8px;\r\n    border-radius: 4px;\r\n    border: 1px solid var(--background-modifier-border);\r\n    background: var(--background-primary);\r\n    cursor: pointer;\r\n}\r\n\r\n.dreamglows-notes-list {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 8px;\r\n}\r\n\r\n.dreamglows-no-content {\r\n    text-align: center;\r\n    padding: 32px;\r\n    color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-note-item {\r\n    padding: 16px;\r\n    background: var(--background-primary);\r\n    border: 1px solid var(--background-modifier-border);\r\n    border-radius: 8px;\r\n    transition: all 0.2s ease;\r\n    cursor: pointer;\r\n}\r\n\r\n.dreamglows-note-item:hover {\r\n    transform: translateX(4px);\r\n    border-color: var(--text-accent);\r\n}\r\n\r\n.dreamglows-note-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: 8px;\r\n}\r\n\r\n.dreamglows-note-title {\r\n    margin: 0;\r\n    font-size: 1.2em;\r\n}\r\n\r\n.dreamglows-header-right {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 16px;\r\n}\r\n\r\n.dreamglows-note-meta {\r\n    display: flex;\r\n    gap: 16px;\r\n    font-size: 0.8em;\r\n    color: var(--text-muted);\r\n    margin-bottom: 8px;\r\n}\r\n\r\n.dreamglows-article-status {\r\n    padding: 4px 8px;\r\n    border-radius: 4px;\r\n    border: none;\r\n    font-size: 0.9em;\r\n    cursor: pointer;\r\n}\r\n\r\n.dreamglows-status-todo {\r\n    background: var(--background-modifier-error);\r\n    color: var(--text-error);\r\n}\r\n\r\n.dreamglows-status-todo option {\r\n    background: var(--background-primary);\r\n    color: white;\r\n}\r\n\r\n.dreamglows-status-in-progress {\r\n    background: var(--background-modifier-warning);\r\n    color: var(--text-warning);\r\n}\r\n\r\n.dreamglows-status-in-progress option {\r\n    background: var(--background-primary);\r\n    color: white;\r\n}\r\n\r\n.dreamglows-status-done {\r\n    background: var(--background-modifier-success);\r\n    color: var(--text-success);\r\n}\r\n\r\n.dreamglows-status-done option {\r\n    background: var(--background-primary);\r\n    color: white;\r\n}\r\n\r\n.view-toggle {\r\n    margin-left: 1rem;\r\n    padding: 0.25rem 0.5rem;\r\n    border-radius: 4px;\r\n    background: var(--interactive-accent);\r\n    color: var(--text-on-accent);\r\n    border: none;\r\n    cursor: pointer;\r\n}\r\n\r\n.view-toggle:hover {\r\n    background: var(--interactive-accent-hover);\r\n}";
