var week_view_default = "/* Styles pour la grille des notes */\r\n.dreamglows-notes-grid {\r\n   display: grid;\r\n   grid-template-columns: repeat(3, 1fr);\r\n   gap: 16px;\r\n   padding: 16px;\r\n}\r\n\r\n/* Styles pour la vue kanban */\r\n.dreamglows-notes-week {\r\n   display: flex;\r\n   flex-direction: column;\r\n   gap: 1rem;\r\n   padding: 1rem;\r\n   width: 100%;\r\n   height: 100%;\r\n   overflow: auto;\r\n}\r\n\r\n.week-header {\r\n   display: grid;\r\n   grid-template-columns: repeat(7, 1fr);\r\n   gap: 0.5rem;\r\n   position: sticky;\r\n   top: 0;\r\n   background: var(--background-primary);\r\n   z-index: 1;\r\n   padding: 0.5rem;\r\n}\r\n\r\n.day-header {\r\n   padding: 0.5rem;\r\n   text-align: center;\r\n   font-weight: bold;\r\n   background: var(--background-secondary);\r\n   border-radius: 4px;\r\n}\r\n\r\n.week-content {\r\n   display: grid;\r\n   grid-template-columns: repeat(7, 1fr);\r\n   gap: 0.5rem;\r\n   min-height: 200px;\r\n   padding: 0.5rem;\r\n}\r\n\r\n.day-content {\r\n   padding: 0.5rem;\r\n   background: var(--background-primary-alt);\r\n   border-radius: 4px;\r\n   min-height: 100%;\r\n   display: flex;\r\n   flex-direction: column;\r\n   gap: 0.5rem;\r\n}\r\n\r\n/* Styles pour les notes dans la vue kanban */\r\n.dreamglows-week-note-item {\r\n   background: var(--background-primary);\r\n   border: 1px solid var(--background-modifier-border);\r\n   border-radius: 4px;\r\n   padding: 0.75rem;\r\n   cursor: pointer;\r\n   transition: all 0.2s ease;\r\n}\r\n\r\n.dreamglows-week-note-item:hover {\r\n   transform: scale(1.02);\r\n   border-color: var(--text-accent);\r\n   background: var(--background-modifier-hover);\r\n}\r\n\r\n.dreamglows-week-note-header {\r\n   display: flex;\r\n   justify-content: space-between;\r\n   align-items: flex-start;\r\n}\r\n\r\n/* Styles pour les notes étendues */\r\n.note-title {\r\n    font-weight: bold;\r\n    margin-bottom: 0.25rem;\r\n}\r\n\r\n.note-details {\r\n    font-size: 0.9em;\r\n    color: var(--text-muted);\r\n}\r\n\r\n.note-tasks {\r\n    margin-top: 0.5rem;\r\n}\r\n\r\n.task-item {\r\n    display: flex;\r\n    gap: 0.5rem;\r\n    align-items: center;\r\n    padding: 0.25rem 0;\r\n}\r\n\r\n/* Styles pour la vue compacte */\r\n.dreamglows-notes-week.compact-view .week-header,\r\n.dreamglows-notes-week.compact-view .week-content {\r\n    grid-template-columns: repeat(3, 1fr);\r\n}\r\n\r\n.weekend-label {\r\n    display: block;\r\n    font-size: 0.9em;\r\n    opacity: 0.8;\r\n}\r\n\r\n/* Styles pour le jour actuel */\r\n.day-header.is-today {\r\n    background: var(--interactive-accent);\r\n    color: var(--text-on-accent);\r\n}\r\n\r\n.day-content.is-today {\r\n    border: 2px solid var(--interactive-accent);\r\n}\r\n\r\n/* Autres styles utilitaires */\r\n.no-notes {\r\n    text-align: center;\r\n    color: var(--text-muted);\r\n    padding: 1rem;\r\n    font-style: italic;\r\n}\r\n\r\n.loading {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    height: 200px;\r\n    color: var(--text-muted);\r\n    font-style: italic;\r\n}\r\n\r\n/* Style pour le conteneur des notes dans un jour */\r\n.day-notes {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 0.5rem;\r\n}";
