var task_list_default = ".dreamglows-task-list {\r\n  width: 100%;\r\n  height: 100%;\r\n  border-left: 1px solid var(--background-modifier-border);\r\n  padding: 1rem;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1rem;\r\n  min-width: 250px;\r\n}\r\n\r\n.dreamglows-task-list-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n\r\n.dreamglows-task-stats {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  padding: 0.5rem;\r\n  background: var(--background-primary);\r\n  border-radius: 4px;\r\n  border: 1px solid var(--background-modifier-border);\r\n}\r\n\r\n.dreamglows-stat-item {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 0.25rem;\r\n}\r\n\r\n.dreamglows-stat-label {\r\n  font-size: 0.8em;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-stat-value {\r\n  font-weight: bold;\r\n  color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-task-search {\r\n  display: flex;\r\n}\r\n\r\n.dreamglows-search-input {\r\n  flex: 1;\r\n  padding: 0.5rem;\r\n  border-radius: 4px;\r\n  border: 1px solid var(--background-modifier-border);\r\n  background-color: var(--background-primary);\r\n  color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-add-task-btn {\r\n  padding: 0.5rem 1rem;\r\n  border-radius: 4px;\r\n  background-color: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n  border: none;\r\n  cursor: pointer;\r\n}\r\n\r\n.dreamglows-task-filters {\r\n  display: flex;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.dreamglows-filter {\r\n  flex: 1;\r\n  padding: 0.25rem;\r\n  border-radius: 4px;\r\n  border: 1px solid var(--background-modifier-border);\r\n  background-color: var(--background-primary);\r\n  color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-tasks-container {\r\n  flex: 1;\r\n  overflow-y: auto;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0.5rem;\r\n  padding: 1rem;\r\n  min-height: 200px;\r\n  background: var(--background-primary);\r\n  border: 1px dashed var(--background-modifier-border);\r\n  border-radius: 4px;\r\n  transition: background-color 0.2s ease;\r\n}\r\n\r\n.dreamglows-tasks-container:hover {\r\n  background: var(--background-primary-alt);\r\n  border-color: var(--interactive-accent);\r\n}\r\n\r\n.dreamglows-tasks-container:empty::after {\r\n  content: \"Double-cliquez pour ajouter une tâche\";\r\n  display: block;\r\n  text-align: center;\r\n  color: var(--text-muted);\r\n  padding: 2rem;\r\n  font-style: italic;\r\n}\r\n\r\n.dreamglows-task-item {\r\n  padding: 0.75rem;\r\n  border-radius: 4px;\r\n  background-color: var(--background-primary-alt);\r\n  border: 1px solid var(--background-modifier-border);\r\n  cursor: pointer;\r\n  transition: all 0.2s ease;\r\n}\r\n\r\n.dreamglows-task-item:hover {\r\n  transform: translateY(-1px);\r\n  box-shadow: var(--shadow-s);\r\n  border-color: var(--interactive-accent);\r\n}\r\n\r\n.dreamglows-task-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 0.5rem;\r\n}\r\n\r\n.dreamglows-task-controls {\r\n  display: flex;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.dreamglows-task-status-btn,\r\n.dreamglows-task-edit-btn {\r\n  background: transparent;\r\n  border: none;\r\n  cursor: pointer;\r\n  padding: 0.25rem;\r\n  border-radius: 4px;\r\n  opacity: 0.7;\r\n  transition: all 0.2s ease;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 24px;\r\n  height: 24px;\r\n  color: var(--text-muted);\r\n  font-size: 1.1em;\r\n}\r\n\r\n.dreamglows-task-status-btn:hover,\r\n.dreamglows-task-edit-btn:hover {\r\n  opacity: 1;\r\n  background-color: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n  transform: translateY(-1px);\r\n  box-shadow: var(--shadow-s);\r\n}\r\n\r\n.dreamglows-task-edit-btn {\r\n  color: var(--text-accent);\r\n  font-weight: bold;\r\n}\r\n\r\n.dreamglows-task-edit-btn i {\r\n  font-size: 0.9em;\r\n}\r\n\r\n.dreamglows-task-priority-btn {\r\n  background: transparent;\r\n  border: none;\r\n  cursor: pointer;\r\n  padding: 0.25rem 0.5rem;\r\n  border-radius: 4px;\r\n  opacity: 0.8;\r\n  transition: all 0.2s ease;\r\n  font-size: 0.9em;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-task-priority-btn:hover {\r\n  opacity: 1;\r\n  background-color: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n  transform: translateY(-1px);\r\n  box-shadow: var(--shadow-s);\r\n}\r\n\r\n.dreamglows-priority-high .dreamglows-task-priority-btn {\r\n  color: var(--text-error);\r\n}\r\n\r\n.dreamglows-priority-medium .dreamglows-task-priority-btn {\r\n  color: var(--text-warning);\r\n}\r\n\r\n.dreamglows-priority-low .dreamglows-task-priority-btn {\r\n  color: var(--text-success);\r\n}\r\n\r\n.dreamglows-task-title {\r\n  font-weight: 500;\r\n  margin-bottom: 0.5rem;\r\n}\r\n\r\n.dreamglows-task-date {\r\n  font-size: 0.9em;\r\n  color: var(--text-muted);\r\n  margin-bottom: 0.5rem;\r\n}\r\n\r\n.dreamglows-task-tags {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 0.25rem;\r\n}\r\n\r\n.dreamglows-tag {\r\n  font-size: 0.8em;\r\n  padding: 0.1rem 0.5rem;\r\n  border-radius: 10px;\r\n  background-color: var(--background-modifier-accent);\r\n  color: var(--text-muted);\r\n}\r\n\r\n/* Priority styles */\r\n.dreamglows-priority-high {\r\n  border-left: 3px solid var(--color-red);\r\n}\r\n\r\n.dreamglows-priority-medium {\r\n  border-left: 3px solid var(--color-orange);\r\n}\r\n\r\n.dreamglows-priority-low {\r\n  border-left: 3px solid var(--color-green);\r\n}\r\n\r\n/* Status styles */\r\n.dreamglows-status-done {\r\n  opacity: 0.7;\r\n}\r\n\r\n.dreamglows-status-in-progress {\r\n  background-color: var(--background-primary);\r\n}";
