var day_view_default = "/* Variables locales pour une meilleure maintenance */\r\n:root {\r\n  --dreamglows-spacing-xs: 0.15rem;\r\n  --dreamglows-spacing-sm: 0.3rem;\r\n  --dreamglows-spacing-md: 0.5rem;\r\n  --dreamglows-spacing-lg: 0.75rem;\r\n  --dreamglows-border-radius: 4px;\r\n  --dreamglows-card-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\n/* Styles communs pour les boutons */\r\n.dreamglows-nav-btn,\r\n.dreamglows-today-btn,\r\n.dreamglows-view-switch button {\r\n  border-radius: var(--dreamglows-border-radius);\r\n  cursor: pointer;\r\n  transition: all 0.2s ease;\r\n  border: none;\r\n}\r\n\r\n/* Layout principal */\r\n.dreamglows-container {\r\n  display: flex;\r\n  flex-direction: column;\r\n  height: 100%;\r\n  width: 100%;\r\n  padding: var(--dreamglows-spacing-md);\r\n  gap: var(--dreamglows-spacing-md);\r\n  background-color: var(--background-primary);\r\n}\r\n\r\n/* En-tête et navigation */\r\n.dreamglows-view-switch {\r\n  display: flex;\r\n  gap: var(--dreamglows-spacing-md);\r\n  padding: var(--dreamglows-spacing-md);\r\n  background-color: var(--background-secondary);\r\n  border-radius: 6px;\r\n}\r\n\r\n.dreamglows-view-switch button {\r\n  padding: var(--dreamglows-spacing-md) var(--dreamglows-spacing-lg);\r\n  background: none;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-view-switch button:hover {\r\n  background-color: var(--background-modifier-hover);\r\n  color: var(--text-normal);\r\n}\r\n\r\n.dreamglows-view-switch button.active {\r\n  background-color: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n}\r\n\r\n.dreamglows-nav-btn {\r\n  padding: var(--dreamglows-spacing-xs) var(--dreamglows-spacing-sm);\r\n  opacity: 0.8;\r\n}\r\n\r\n.dreamglows-nav-btn:hover {\r\n  opacity: 1;\r\n  background-color: var(--background-modifier-hover);\r\n}\r\n\r\n.dreamglows-today-btn {\r\n  padding: var(--dreamglows-spacing-md) var(--dreamglows-spacing-lg);\r\n  background-color: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n}\r\n\r\n/* Styles communs pour les cartes */\r\n.dreamglows-summary-card,\r\n.dreamglows-habits-section {\r\n  background-color: var(--background-primary);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  border: 1px solid var(--background-modifier-border);\r\n  box-shadow: var(--dreamglows-card-shadow);\r\n  padding: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n/* Cartes de résumé */\r\n.dreamglows-day-summary {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\r\n  gap: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-summary-card.progression-card .dreamglows-card-content {\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-card-content {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--dreamglows-spacing-xs);\r\n  margin-top: var(--dreamglows-spacing-xs);\r\n}\r\n\r\n.dreamglows-progress-bar-wrap {\r\n  width: 100%;\r\n  height: 0.35rem;\r\n  background-color: var(--background-modifier-hover);\r\n  border-radius: 999px;\r\n  overflow: hidden;\r\n}\r\n\r\n.dreamglows-progress-bar {\r\n  height: 100%;\r\n  background-color: var(--interactive-accent);\r\n}\r\n\r\n.dreamglows-reward-list {\r\n  width: 100%;\r\n  margin-top: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-reward-list-inner {\r\n  margin: var(--dreamglows-spacing-sm) 0 0;\r\n  padding: 0;\r\n  list-style: none;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--dreamglows-spacing-xs);\r\n}\r\n\r\n.dreamglows-reward-list-inner li {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  gap: var(--dreamglows-spacing-sm);\r\n  font-size: 0.8em;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-reward-date {\r\n  opacity: 0.7;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dreamglows-card-text {\r\n  flex: 1;\r\n}\r\n\r\n.dreamglows-card-title {\r\n  font-weight: 500;\r\n}\r\n\r\n.dreamglows-card-subtitle {\r\n  font-size: 0.8em;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-day-view {\r\n  height: 100%;\r\n  padding: var(--dreamglows-spacing-sm);\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--dreamglows-spacing-md);\r\n  overflow-y: auto;\r\n}\r\n\r\n/* En-tête et navigation */\r\n.dreamglows-day-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-day-navigation {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-nav-btn {\r\n  padding: var(--dreamglows-spacing-xs) var(--dreamglows-spacing-sm);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  opacity: 0.8;\r\n  transition: all 0.2s ease;\r\n}\r\n\r\n.dreamglows-nav-btn:hover {\r\n  opacity: 1;\r\n  background-color: var(--background-modifier-hover);\r\n}\r\n\r\n.dreamglows-today-btn {\r\n  padding: 0.5rem 1rem;\r\n  border-radius: 4px;\r\n  background-color: var(--interactive-accent);\r\n  color: var(--text-on-accent);\r\n  border: none;\r\n  cursor: pointer;\r\n}\r\n\r\n/* Section des habitudes */\r\n.dreamglows-habits-section {\r\n  position: relative;\r\n  background-color: var(--background-primary);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  border: 1px solid var(--background-modifier-border);\r\n  overflow: hidden;\r\n  padding: var(--dreamglows-spacing-md);\r\n  box-shadow: var(--dreamglows-card-shadow);\r\n}\r\n\r\n/* Barre de progression */\r\n.dreamglows-habits-background {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n  z-index: 0;\r\n  pointer-events: none;\r\n}\r\n\r\n.progress-background {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  height: 100%;\r\n  background-color: var(--interactive-accent);\r\n  opacity: 0.2;\r\n  transition: width 0.3s ease;\r\n  z-index: 1;\r\n}\r\n\r\n/* Calendrier des flammes */\r\n.dreamglows-flames-calendar {\r\n  position: relative;\r\n  z-index: 2;\r\n  width: 100%;\r\n  padding: var(--dreamglows-spacing-xs) 0;\r\n  max-height: calc(4 * (1em + var(--dreamglows-spacing-md) * 2));\r\n  overflow: hidden;\r\n}\r\n\r\n.dreamglows-flames-calendar.mobile {\r\n  max-height: calc(3 * (2em + var(--dreamglows-spacing-md) * 2));\r\n}\r\n\r\n.dreamglows-flames-calendar.mobile .dreamglows-flames-row {\r\n  flex-direction: column;\r\n  gap: var(--dreamglows-spacing-md);\r\n}\r\n\r\n.dreamglows-flames-calendar.mobile .dreamglows-month-flames {\r\n  flex: 1 1 100%;\r\n  max-width: 100%;\r\n}\r\n\r\n.dreamglows-flames-calendar.mobile .dreamglows-flame-day {\r\n  font-size: clamp(0.8em, calc(0.6em + 1.8vw), 2.8em);\r\n  margin: 0 -0.5em !important;\r\n  opacity: 0.4;\r\n}\r\n\r\n.dreamglows-flames-calendar.mobile .dreamglows-flame-day.completed {\r\n  opacity: 1;\r\n}\r\n\r\n.dreamglows-flames-calendar.mobile .dreamglows-flame-day.future {\r\n  opacity: 0.15;\r\n}\r\n\r\n.dreamglows-flames-row {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--dreamglows-spacing-md) 1.5rem;\r\n  padding-top: var(--dreamglows-spacing-md);\r\n  padding-bottom: var(--dreamglows-spacing-md);\r\n  width: 100%;\r\n}\r\n\r\n.dreamglows-month-flames {\r\n  display: flex;\r\n  padding: 0;\r\n  margin: 0;\r\n  align-items: flex-start;\r\n  position: relative;\r\n  transition: transform 0.2s ease;\r\n  flex: 1 1 calc(33.33% - 1.5rem);\r\n  min-width: calc(33.33% - 1.5rem);\r\n  max-width: calc(33.33% - 1.5rem);\r\n}\r\n\r\n/* Styles communs pour les flammes */\r\n.dreamglows-flame-day,\r\n.flame-emoji {\r\n  padding: 0 !important;\r\n  margin: 0 !important;\r\n  width: auto !important;\r\n  display: flex !important;\r\n  align-items: flex-start !important;\r\n  justify-content: center;\r\n  line-height: 1 !important;\r\n  flex: 1;\r\n}\r\n\r\n.dreamglows-flame-day {\r\n  font-size: clamp(0.4em, calc(0.3em + 1vw), 2.2em);\r\n  opacity: 0.4;\r\n  cursor: pointer;\r\n  margin: 0 calc(-0.3em - 0.1vw) !important;\r\n  width: auto !important;\r\n  display: flex !important;\r\n  align-items: flex-start !important;\r\n  justify-content: center;\r\n  flex: 1;\r\n}\r\n\r\n.flame-emoji {\r\n  display: inline-block !important;\r\n  width: auto !important;\r\n  padding: 0 !important;\r\n  margin: 0 !important;\r\n  line-height: 1 !important;\r\n  text-align: center !important;\r\n  vertical-align: top !important;\r\n}\r\n\r\n.dreamglows-flame-day.completed {\r\n  opacity: 1;\r\n}\r\n\r\n.dreamglows-flame-day.future {\r\n  opacity: 0.15;\r\n}\r\n\r\n/* Tooltip pour le nom du mois */\r\n.dreamglows-month-flames::before {\r\n  content: attr(data-month);\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 50%;\r\n  transform: translate(-50%, -50%);\r\n  padding: 0.15rem 0.3rem;\r\n  background-color: var(--background-primary);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  font-size: 0.9em;\r\n  font-weight: 500;\r\n  color: var(--text-normal);\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  transition: opacity 0.2s ease;\r\n  pointer-events: none;\r\n  white-space: nowrap;\r\n  z-index: 10;\r\n}\r\n\r\n.dreamglows-month-flames:hover::before {\r\n  opacity: 0.95;\r\n  visibility: visible;\r\n}\r\n\r\n/* Grille des habitudes */\r\n.dreamglows-habits-grid {\r\n  position: relative;\r\n  z-index: 2;\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));\r\n  gap: var(--dreamglows-spacing-xs);\r\n  margin-bottom: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-habit-card {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: var(--dreamglows-spacing-xs);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  background-color: var(--background-primary-alt);\r\n  border: 1px solid var(--background-modifier-border);\r\n  transition: all 0.2s ease;\r\n  cursor: pointer;\r\n  position: relative;\r\n  overflow: visible;\r\n}\r\n\r\n.dreamglows-habit-icon {\r\n  font-size: 2.4em;\r\n  z-index: 2;\r\n}\r\n\r\n.dreamglows-habit-week {\r\n  position: absolute;\r\n  left: 3em;\r\n  right: 4em;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.dreamglows-habit-day {\r\n  font-size: 1.8em;\r\n  opacity: 0.4;\r\n  cursor: pointer;\r\n  flex: 1;\r\n  text-align: center;\r\n  min-width: 0;\r\n  display: flex;\r\n  justify-content: center;\r\n  transition: opacity 0.2s ease;\r\n  position: relative;\r\n}\r\n\r\n.dreamglows-habit-day::before {\r\n  content: attr(data-day);\r\n  position: absolute;\r\n  top: -1.5em;\r\n  left: 50%;\r\n  transform: translateX(-50%);\r\n  padding: 0.15rem 0.3rem;\r\n  background-color: var(--background-primary);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  font-size: 0.4em;\r\n  font-weight: 500;\r\n  color: var(--text-normal);\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  transition: opacity 0.2s ease;\r\n  pointer-events: none;\r\n  white-space: nowrap;\r\n  z-index: 10;\r\n}\r\n\r\n.dreamglows-habit-day:hover::before {\r\n  opacity: 0.95;\r\n  visibility: visible;\r\n}\r\n\r\n.dreamglows-habit-day.completed {\r\n  opacity: 1;\r\n}\r\n\r\n.dreamglows-habit-day.future {\r\n  opacity: 0.15;\r\n}\r\n\r\n/* Ajustement de l'overlap en fonction de la largeur */\r\n@media screen and (max-width: 600px) {\r\n  .dreamglows-habit-week {\r\n    left: 2.5em;\r\n    right: 3.5em;\r\n  }\r\n  .dreamglows-habit-day {\r\n    margin: 0 -0.4em;\r\n  }\r\n}\r\n\r\n@media screen and (max-width: 400px) {\r\n  .dreamglows-habit-week {\r\n    left: 2em;\r\n    right: 3em;\r\n  }\r\n  .dreamglows-habit-day {\r\n    margin: 0 -0.6em;\r\n  }\r\n}\r\n\r\n.dreamglows-habit-info {\r\n  display: none;\r\n}\r\n\r\n.dreamglows-habit-target {\r\n  font-size: 0.8em;\r\n  padding: var(--dreamglows-spacing-xs) var(--dreamglows-spacing-sm);\r\n  background-color: var(--background-modifier-hover);\r\n  border-radius: 4px;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dreamglows-habit-card:hover {\r\n  background-color: var(--background-modifier-hover);\r\n}\r\n\r\n.dreamglows-habit-card.completed {\r\n  background-color: var(--interactive-success);\r\n  color: var(--text-on-accent);\r\n}\r\n\r\n/* Humeur et énergie */\r\n.dreamglows-mood-row {\r\n  display: flex;\r\n  width: 100%;\r\n  margin-top: var(--dreamglows-spacing-sm);\r\n  gap: calc(var(--dreamglows-spacing-lg) * 2);\r\n}\r\n\r\n.dreamglows-mood-line {\r\n  display: flex;\r\n  width: 100%;\r\n  justify-content: center;\r\n}\r\n\r\n.dreamglows-mood-line:last-child {\r\n  justify-content: center;\r\n  gap: calc(var(--dreamglows-spacing-lg) * 3);\r\n}\r\n\r\n.dreamglows-mood-item {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  flex: 1;\r\n}\r\n\r\n.dreamglows-mood-buttons {\r\n  display: flex;\r\n  white-space: nowrap;\r\n  justify-content: center;\r\n  gap: 1px;\r\n  width: 100%;\r\n  min-width: 0;\r\n}\r\n\r\n.dreamglows-mood-btn,\r\n.dreamglows-energy-btn {\r\n  flex: 1;\r\n  aspect-ratio: 1.2;\r\n  padding: 1px;\r\n  border-radius: var(--dreamglows-border-radius);\r\n  font-size: min(1.8em, calc((100vw - 4rem) / 75));\r\n  transition: opacity 0.2s ease;\r\n  opacity: 0.4;\r\n  cursor: pointer;\r\n  background: none;\r\n  border: none;\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  min-width: 0;\r\n}\r\n\r\n.dreamglows-mood-btn:hover,\r\n.dreamglows-energy-btn:hover {\r\n  opacity: 0.7;\r\n}\r\n\r\n.dreamglows-mood-btn.active,\r\n.dreamglows-energy-btn.active {\r\n  opacity: 1;\r\n}\r\n\r\n/* Section des notes avec hauteur dynamique */\r\n.dreamglows-notes-section {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-height: 0; /* Important pour que flex: 1 fonctionne correctement */\r\n  margin-top: var(--dreamglows-spacing-sm);\r\n  padding: var(--dreamglows-spacing-sm);\r\n  background: var(--background-primary);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  box-shadow: var(--dreamglows-card-shadow);\r\n}\r\n\r\n.dreamglows-note-viewer {\r\n  margin-top: var(--dreamglows-spacing-xs);\r\n  border: 1px solid var(--background-modifier-border);\r\n  border-radius: var(--dreamglows-border-radius);\r\n  min-height: 150px;\r\n  max-height: 400px;\r\n  overflow-y: auto;\r\n}\r\n\r\n.dreamglows-note-content {\r\n  padding: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n.dreamglows-note-empty {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 2rem;\r\n  text-align: center;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.dreamglows-generate-btn:hover {\r\n  background: var(--interactive-accent-hover);\r\n}\r\n\r\n/* Styles Markdown */\r\n:deep(.markdown-preview-view) {\r\n  height: 100%;\r\n  padding: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n:deep(.markdown-preview-view h1) {\r\n  margin-top: 0;\r\n  font-size: 1.3em;\r\n}\r\n\r\n:deep(.markdown-preview-view h2) {\r\n  font-size: 1.1em;\r\n  padding-bottom: var(--dreamglows-spacing-xs);\r\n  margin: var(--dreamglows-spacing-sm) 0;\r\n}\r\n\r\n/* Optimisations pour le mode édition */\r\n:deep(.markdown-source-view) {\r\n  height: 100%;\r\n}\r\n\r\n:deep(.cm-editor) {\r\n  height: 100%;\r\n}\r\n\r\n:deep(.cm-scroller) {\r\n  padding: var(--dreamglows-spacing-sm);\r\n}\r\n\r\n/* Scrollbar optimisée */\r\n.dreamglows-note-content::-webkit-scrollbar {\r\n  width: 6px;\r\n}\r\n\r\n.dreamglows-note-content::-webkit-scrollbar-track {\r\n  background: transparent;\r\n}\r\n\r\n.dreamglows-note-content::-webkit-scrollbar-thumb {\r\n  background: var(--interactive-accent);\r\n  border-radius: var(--dreamglows-border-radius);\r\n}\r\n\r\n/* Optimisations générales */\r\n.setting-item,\r\n.setting-item-control {\r\n  padding: 0;\r\n  border: none;\r\n}\r\n\r\nh2, h3 {\r\n  margin: 0;\r\n  font-size: 1.1em;\r\n}\r\n\r\n/* Masquer la barre de défilement mais garder la fonctionnalité */\r\n.dreamglows-flames-calendar::-webkit-scrollbar {\r\n  display: none;\r\n}\r\n\r\n.dreamglows-flames-calendar {\r\n  -ms-overflow-style: none;\r\n  scrollbar-width: none;\r\n}\r\n\r\n/* Version mobile */\r\n@media screen and (max-width: 768px) {\r\n  .dreamglows-flames-calendar {\r\n    max-height: none !important;\r\n  }\r\n\r\n  .dreamglows-flames-row {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 1rem;\r\n  }\r\n\r\n  .dreamglows-month-flames {\r\n    width: 100%;\r\n  }\r\n\r\n  .dreamglows-flame-day {\r\n    font-size: clamp(0.8em, calc(0.6em + 1.8vw), 2.8em);\r\n    margin: 0 -0.5em !important;\r\n    opacity: 0.4;\r\n  }\r\n\r\n  .dreamglows-mood-row {\r\n    flex-direction: column;\r\n    gap: var(--dreamglows-spacing-lg);\r\n  }\r\n  \r\n  .dreamglows-mood-btn,\r\n  .dreamglows-energy-btn {\r\n    font-size: min(1.8em, calc((100vw - 2rem) / 15));\r\n  }\r\n}\r\n";
