//#region src/views/DreamGlowsView.ts
var DreamGlowsView = class extends obsidian.ItemView {
	constructor(leaf, plugin) {
		super(leaf);
		this.plugin = plugin;
	}
	getViewType() {
		return "dreamglows-view";
	}
	getDisplayText() {
		return "DreamGlows";
	}
	getIcon() {
		return "target";
	}
	async onOpen() {
		const container = this.containerEl.children[1];
		container.empty();
		container.createEl("div", { cls: "dreamglows-container" });
		registerStyles("all");
		this.vueApp = createApp(MainView_default, {
			contentFiles: this.app.vault.getMarkdownFiles(),
			app: this.app
		});
		this.vueApp.use(this.plugin.pinia);
		this.vueApp.provide(PATH_COMMAND_PORT_KEY, this.plugin.pathCommands);
		this.vueApp.provide(DREAMGLOWS_UI_CONTEXT_KEY, {
			pinia: this.plugin.pinia,
			pathCommands: this.plugin.pathCommands,
			entityEditor: this.plugin.entityEditor
		});
		this.vueApp.mount(container.children[0]);
	}
	async onClose() {
		if (this.vueApp) this.vueApp.unmount();
	}
};
