//#region src/types/models.ts
var MetricsSchema = objectType({
	current: numberType().min(0),
	target: numberType().min(0),
	unit: stringType().min(1)
}).refine((data) => data.current <= data.target, { message: "La valeur actuelle ne peut pas dépasser la cible" });
var StatusSchema = enumType([
	"todo",
	"in-progress",
	"done"
]);
var PrioritySchema = enumType([
	"low",
	"medium",
	"high"
]);
var baseItemFields = {
	id: stringType().uuid(),
	title: stringType().min(1).max(100).trim(),
	description: stringType().default(""),
	status: StatusSchema,
	priority: PrioritySchema,
	tags: arrayType(stringType().trim()).default([]),
	startDate: stringType().datetime(),
	dueDate: stringType().datetime()
};
objectType(baseItemFields).refine((data) => new Date(data.startDate) <= new Date(data.dueDate), { message: "La date de début doit être antérieure ou égale à la date de fin" });
var GoalSchema = objectType({
	...baseItemFields,
	category: stringType().min(1).trim(),
	progress: numberType().min(0).max(100).default(0),
	metrics: MetricsSchema.optional(),
	tasks: arrayType(stringType().uuid()).default([]),
	subGoalIds: arrayType(stringType().uuid()).default([]),
	timeframe: stringType().min(1).max(100).trim(),
	parentGoalId: stringType().uuid().optional(),
	childGoals: arrayType(stringType().uuid()).optional(),
	status: enumType([
		"todo",
		"in-progress",
		"done",
		"completed"
	])
});
var TaskSchema = objectType({
	...baseItemFields,
	goalId: stringType().uuid().optional(),
	notes: stringType().default(""),
	createdAt: stringType().datetime(),
	updatedAt: stringType().datetime(),
	completedAt: stringType().datetime().optional(),
	priority: PrioritySchema,
	status: StatusSchema
}).refine((data) => new Date(data.updatedAt) >= new Date(data.createdAt), { message: "La date de mise à jour doit être postérieure ou égale à la date de création" });
objectType({
	mood: numberType().int().min(1).max(5),
	energyLevel: numberType().int().min(1).max(5),
	notes: stringType().optional(),
	timestamp: stringType().datetime()
});
var DataStoreSchema = objectType({
	goals: arrayType(GoalSchema),
	tasks: arrayType(TaskSchema)
});
objectType({
	type: enumType([
		"goal:created",
		"goal:updated",
		"goal:deleted",
		"task:created",
		"task:updated",
		"task:deleted",
		"mood:updated",
		"data:synced",
		"stats:updated"
	]),
	payload: unknownType(),
	timestamp: stringType().datetime()
});
var DayStatsSchema = objectType({
	mood: numberType().int().min(1).max(5).optional(),
	energyLevel: numberType().int().min(1).max(5).optional(),
	completionRate: numberType().min(0).max(100).optional(),
	completedTasks: numberType().int().min(0)
});
var CategoryStatsSchema = objectType({
	total: numberType().int().min(0),
	completed: numberType().int().min(0),
	inProgress: numberType().int().min(0),
	todo: numberType().int().min(0),
	completionRate: numberType().min(0).max(100)
}).refine((data) => data.completed + data.inProgress + data.todo === data.total, { message: "La somme des statuts doit être égale au total" });
objectType({
	startDate: stringType().datetime(),
	endDate: stringType().datetime(),
	goals: CategoryStatsSchema,
	tasks: objectType({
		total: numberType().int().min(0),
		completed: numberType().int().min(0),
		completionRate: numberType().min(0).max(100),
		dailyAverage: numberType().min(0)
	}),
	categories: recordType(stringType(), CategoryStatsSchema),
	dailyStats: recordType(stringType(), DayStatsSchema)
}).refine((data) => new Date(data.startDate) <= new Date(data.endDate), { message: "La date de début doit être antérieure ou égale à la date de fin" });
